import os
from typing import Any, Dict, Optional
from urllib.parse import urlencode

import msal
from flask import Flask, jsonify, redirect, request, session

app = Flask(__name__)
app.secret_key = os.environ.get("FLASK_SECRET_KEY", "change-me")

AZURE_TENANT_ID = os.environ.get("AZURE_TENANT_ID", "common")
AZURE_CLIENT_ID = os.environ.get("AZURE_CLIENT_ID")
AZURE_CLIENT_SECRET = os.environ.get("AZURE_CLIENT_SECRET")
AZURE_REDIRECT_URI = os.environ.get("AZURE_REDIRECT_URI", "http://localhost:5000/callback")
AZURE_AUTHORITY = f"https://login.microsoftonline.com/{AZURE_TENANT_ID}"
AZURE_SCOPES = ["openid", "profile", "email", "offline_access", "User.Read"]


def _build_app() -> msal.ConfidentialClientApplication:
    if not AZURE_CLIENT_ID or not AZURE_CLIENT_SECRET:
        raise RuntimeError("AZURE_CLIENT_ID and AZURE_CLIENT_SECRET must be set")
    return msal.ConfidentialClientApplication(
        client_id=AZURE_CLIENT_ID,
        authority=AZURE_AUTHORITY,
        client_credential=AZURE_CLIENT_SECRET,
    )


@app.route("/login")
def login() -> Any:
    app_obj = _build_app()
    auth_url = app_obj.get_authorization_request_url(
        scopes=AZURE_SCOPES,
        redirect_uri=AZURE_REDIRECT_URI,
        state="login-state",
        response_mode="query",
    )
    return redirect(auth_url)


@app.route("/callback")
def callback() -> Any:
    error = request.args.get("error")
    if error:
        return jsonify(
            {
                "error": error,
                "error_description": request.args.get("error_description"),
                "error_uri": request.args.get("error_uri"),
            }
        ), 400

    code = request.args.get("code")
    if not code:
        return jsonify({"error": "missing_authorization_code"}), 400

    app_obj = _build_app()
    token_result: Dict[str, Any] = app_obj.acquire_token_by_authorization_code(
        code=code,
        scopes=AZURE_SCOPES,
        redirect_uri=AZURE_REDIRECT_URI,
    )

    if "error" in token_result:
        return jsonify(token_result), 400

    session["token_result"] = token_result
    return jsonify(
        {
            "access_token": token_result.get("access_token"),
            "id_token": token_result.get("id_token"),
            "refresh_token": token_result.get("refresh_token"),
            "expires_in": token_result.get("expires_in"),
            "scope": token_result.get("scope"),
            "token_type": token_result.get("token_type"),
        }
    )


@app.route("/userinfo")
def userinfo() -> Any:
    token_result: Optional[Dict[str, Any]] = session.get("token_result")
    if not token_result or not token_result.get("access_token"):
        return jsonify({"error": "not_authenticated"}), 401

    import requests

    resp = requests.get(
        "https://graph.microsoft.com/v1.0/me",
        headers={"Authorization": f"Bearer {token_result['access_token']}"},
        timeout=10,
    )
    if not resp.ok:
        return jsonify({"error": "userinfo_failed", "details": resp.text}), resp.status_code
    return jsonify(resp.json())


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", "5000")), debug=True)
